def fonte(n):
    return open(os.path.join(DES, n), encoding='utf-8').read()

def gravar(nome, obj):
    with open(os.path.join(OUT, nome), 'w', encoding='utf-8', newline='\n') as f:
        json.dump(obj, f, ensure_ascii=False, indent=1)

