    gravar('propor_modelo.json', {'modelo': modelo, 'motivo': 'o desafio final pelo motor fechado: o núcleo como L que compõe (peças de primitivas), a vida v2 com contexto, a foto de bits (respostas e etiquetas de 5 sondas por vida) para a novidade por Hamming, o efeito no meio declarado nulo (a vida não reage ao aprendiz) e o domínio de M declarado'})
    gravar('formular_D.json', {'clausulas': D + OBJ, 'escopo': ESCOPO, 'ambiguidades': [], 'condicoes_de_uso': ['vale para vidas com o contexto da tarefa na entrada; a prova cega usa outra família, outra semente e outra vida']})
