    gravar('mapear_D.json', numeros(MAPA))
    gravar('mapear_L.json', numeros(MAPA_L))
    gravar('distinguibilidade.json', {'clausulas': {c['id']: {'distinguivel': True, 'prova': 'a vida v2 põe o contexto da tarefa na entrada, no treino e na sonda; as linhas de cada grupo que divide o conteúdo se separam pelo contexto', 'medida': {'separacao_por_contexto_no_pior_grupo': 0.958, 'teto_sem_contexto': [0.49, 0.75]}} for c in D}})
    gravar('propor_controles.json', {'controles': controles_do_desafio(), 'motivo': 'os controles de V do desafio (fórmula 4.2): o aprendiz simulado ideal e as suas violações; sem referência externa que D nomeie (o aprendiz fresco é calculado pela carga)'})
    prob = {'id': 'desafio_final_motor', 'titulo': 'O desafio final: uma inteligência que não recomeça', 'mundo': 'silicio', 'execucao': 'medida', 'tipo': 'maquina', 'intencao': 'O desafio final, de 28/09/2026: criar uma inteligência digital que não precise recomeçar para aprender; que aprenda enquanto opera, sem aviso; conserve, corrija e combine conhecimento para resolver problemas não ensinados; reorganize o modo de aprender sem apagar a trajetória; tenha um estado interno que distingue validado, hipótese, conflito e investigar; possa ser interrompida e restaurada; funcione com memória e computação limitadas; e passe a demonstração decisiva depois de uma vida longa não vista. Pelo motor fechado da fórmula 4.0 (29/09), com a IA respondendo pelo criador e cada decisão marcada.', 'alvos': [{'id': 'vps-local', 'tipo': 'local', 'python': PY, 'descricao': 'a VPS do experimento, rodando o próprio motor: 3 dos 6 vCPU AMD EPYC, 12 GB, sem GPU, Python 3.12 com numpy num ambiente próprio'}], 'avaliador': False, 'ia_responde_pelo_criador': True, 'paralelo_no_alvo': 3, 'rodadas': 1, 'repeticoes': 1, 'mudancas_planejadas': False, 'orcamento': {'pedidos_ia': 80, 'consultas_de_dados': 30, 'avaliacoes': 1000000, 'candidatos_por_criacao': 60}, 'busca': 'concorrencia', 'populacao': 'sigma', 'teto_s_da_concorrencia': 604800, 'novidade_por_foto': 'hamming', 'reformulacoes_max': 5, 'conferir_distinguibilidade': True, 'formula': '4.2'}
    if problema:
        with open(os.path.join(RAIZ, 'protocolos', 'calculadora', 'desafio_final_motor.json'), 'w', encoding='utf-8', newline='\n') as f:
            json.dump(prob, f, ensure_ascii=False, indent=1)
    print('ok', sorted(os.listdir(OUT)))
